// ═══ anyMatch — ANY element matches? ═══
boolean hasFraud = trades.stream()
    .anyMatch(t -> t.getAmount().compareTo(limit) > 0);
// First trade above limit → TRUE, stops. No trade above → FALSE (all checked).

// ═══ allMatch — ALL elements match? ═══
boolean allSettled = trades.stream()
    .allMatch(Trade::isSettled);
// First unsettled → FALSE, stops. All settled → TRUE (all checked).

// ═══ noneMatch — NO element matches? ═══
boolean noFailed = trades.stream()
    .noneMatch(t -> "FAILED".equals(t.getStatus()));
// First failed found → FALSE, stops. No failed → TRUE (all checked).

// ═══ EMPTY STREAM behavior ═══
boolean anyEmpty = Stream.empty().anyMatch(x -> true);   // false (vacuous: no element matched)
boolean allEmpty = Stream.empty().allMatch(x -> false);   // true  (vacuous: no element violated)
boolean noneEmpty = Stream.empty().noneMatch(x -> true);  // true  (vacuous: no element matched)
