package com.bank.match;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class MatchOpsTest {

    @Test void anyMatchShortCircuits() {
        AtomicInteger checks = new AtomicInteger(0);
        boolean found = Stream.of(1, 2, 3, 4, 5)
            .peek(n -> checks.incrementAndGet())
            .anyMatch(n -> n == 3);
        assertThat(found).isTrue();
        assertThat(checks.get()).isEqualTo(3);  // stopped at 3, didn't check 4,5
    }

    @Test void allMatchShortCircuits() {
        AtomicInteger checks = new AtomicInteger(0);
        boolean all = Stream.of(2, 4, 5, 6, 8)
            .peek(n -> checks.incrementAndGet())
            .allMatch(n -> n % 2 == 0);
        assertThat(all).isFalse();  // 5 is odd
        assertThat(checks.get()).isEqualTo(3);  // stopped at 5
    }

    @Test void noneMatchShortCircuits() {
        AtomicInteger checks = new AtomicInteger(0);
        boolean none = Stream.of("OK", "OK", "FAILED", "OK")
            .peek(s -> checks.incrementAndGet())
            .noneMatch(s -> s.equals("FAILED"));
        assertThat(none).isFalse();
        assertThat(checks.get()).isEqualTo(3);  // stopped at FAILED
    }

    @Test void emptyStreamBehavior() {
        assertThat(Stream.empty().anyMatch(x -> true)).isFalse();
        assertThat(Stream.empty().allMatch(x -> false)).isTrue();
        assertThat(Stream.empty().noneMatch(x -> true)).isTrue();
    }

    @Test void logicalRelationship() {
        List<Integer> nums = List.of(1, 2, 3, 4, 5);
        // noneMatch(pred) == !anyMatch(pred)
        assertThat(nums.stream().noneMatch(n -> n > 10))
            .isEqualTo(!nums.stream().anyMatch(n -> n > 10));
    }
}
