package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import static org.assertj.core.api.Assertions.assertThat;

class MatchTest {

    @Test
    void shortCircuitingMatches() {
        List<Integer> amounts = List.of(5000, 20000, 150000, 3000);

        assertThat(amounts.stream().anyMatch(a -> a > 100000)).isTrue();   // stops at 150000
        assertThat(amounts.stream().allMatch(a -> a > 0)).isTrue();        // all positive
        assertThat(amounts.stream().noneMatch(a -> a < 0)).isTrue();       // none negative

        assertThat(List.<Integer>of().allMatch(a -> a > 0)).isTrue();      // vacuously true
        assertThat(List.<Integer>of().anyMatch(a -> a > 0)).isFalse();     // nothing matched
    }
}
